const images = {"candi_bg": "", "solo_basahan": "", "jawi_jangkep": "", "kebaya_kartini": ""};

const hashes = {};
for (const [key, b64] of Object.entries(images)) {
  const bytes = figma.base64Decode(b64);
  const img = figma.createImage(bytes);
  figma.root.setPluginData('javara_' + key, img.hash);
  hashes[key] = img.hash;
}
return hashes;
